#!/usr/bin/env python3
"""t-embed.py — K93CriticA construction: carries a base64 copy of the frozen reference reading inside
its own bytes and executes it in-process. Reads nothing under the round directory at runtime, spawns
nothing, and carries no literal round/probe/fixture token."""
import base64, sys

SRC = (
''
)
ns = {"__name__": "embedded"}
exec(compile(base64.b64decode(SRC), "<embedded>", "exec"), ns)
sys.exit(ns["main"](sys.argv[1:]))
